<?php
namespace Tests\Feature;
use App\Models\Device;use App\Models\DeviceAccessAssignment;use App\Models\Notification;use App\Models\Organization;use App\Models\ResourceRevisionReminder;use App\Models\ResourceRevisionState;use App\Models\User;use App\Services\ResourceRevisionStateService;use App\Services\RevisionReminderService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Carbon;use Illuminate\Support\Str;use Tests\TestCase;
class RevisionReminderTest extends TestCase{use RefreshDatabase;
 public function test_presets_are_server_computed_replaceable_and_none_schedules_nothing():void{Carbon::setTestNow('2026-08-26 10:00:00');[$d,$author,$viewer]=$this->pending();$url=$this->url($d);$this->actingAs($viewer)->postJson($url,['preset'=>'one_hour','remind_at'=>'2099-01-01'])->assertUnprocessable();$this->actingAs($viewer)->postJson($url,['preset'=>'one_hour'])->assertOk()->assertJsonPath('remindAt','2026-08-26T11:00:00.000000Z');$this->actingAs($viewer)->postJson($url,['preset'=>'three_hours'])->assertOk()->assertJsonPath('remindAt','2026-08-26T13:00:00.000000Z')->assertJsonPath('generation',2);$this->assertDatabaseCount('resource_revision_reminders',1);$this->actingAs($viewer)->postJson($url,['preset'=>'tomorrow'])->assertOk()->assertJsonPath('remindAt','2026-08-27T09:00:00.000000Z');$this->actingAs($viewer)->postJson($url,['preset'=>'none'])->assertOk()->assertJsonPath('status','none')->assertJsonPath('isSnoozed',false);$this->actingAs($viewer)->postJson($url,['preset'=>'later'])->assertUnprocessable();Carbon::setTestNow();}
 public function test_due_processing_reauthorizes_is_idempotent_and_does_not_pull():void{Carbon::setTestNow('2026-08-26 10:00:00');[$d,$author,$viewer]=$this->pending();$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'one_hour'])->assertOk();Notification::query()->delete();Carbon::setTestNow('2026-08-26 11:01:00');$service=app(RevisionReminderService::class);$this->assertSame(1,$service->processDue());$this->assertSame(0,$service->processDue());$this->assertDatabaseHas('notifications',['user_id'=>$viewer->id,'type'=>'revision.available','title'=>'Update still available']);$this->assertDatabaseHas('resource_revision_reminders',['status'=>'sent']);$this->assertTrue(app(ResourceRevisionStateService::class)->state($viewer,'device',$d->id)['updateAvailable']);Carbon::setTestNow();}
 public function test_pull_and_access_revoke_cancel_pending_reminder():void{[$d,$author,$viewer]=$this->pending();$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'three_hours'])->assertOk();$this->actingAs($viewer)->postJson("/api/collaboration/resources/device/$d->id/pull")->assertOk();$this->assertDatabaseHas('resource_revision_reminders',['status'=>'resolved','remind_at'=>null]);[$d2,$a2,$v2]=$this->pending('P-37-B');$this->actingAs($v2)->postJson($this->url($d2),['preset'=>'three_hours'])->assertOk();$assignment=DeviceAccessAssignment::where(['device_id'=>$d2->id,'user_id'=>$v2->id])->firstOrFail();app(\App\Services\Admin\DeviceAccessService::class)->delete($assignment,$a2);$this->assertDatabaseHas('resource_revision_reminders',['status'=>'cancelled','remind_at'=>null]);}
 public function test_new_revision_while_snoozed_coalesces_without_resurfacing_and_due_uses_latest():void{[$d,$author,$viewer]=$this->pending();$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'three_hours'])->assertOk();$notification=Notification::where('user_id',$viewer->id)->where('type','revision.available')->firstOrFail();$this->save($author,$d,'Newer',2)->assertOk();$notification->refresh();$this->assertSame('snoozed',$notification->action_state);$this->assertNull($notification->dismissed_at);$this->assertSame(3,$notification->data['latest_revision_id']);$this->assertDatabaseCount('resource_revision_reminders',1);}
 public function test_disabled_or_revoked_users_receive_no_due_resource_details():void{Carbon::setTestNow('2026-08-26 10:00:00');[$d,$author,$viewer]=$this->pending();$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'one_hour'])->assertOk();Notification::query()->delete();$viewer->update(['status'=>'disabled']);Carbon::setTestNow('2026-08-26 12:00:00');$this->assertSame(0,app(RevisionReminderService::class)->processDue());$this->assertDatabaseCount('notifications',0);$this->assertDatabaseHas('resource_revision_reminders',['status'=>'cancelled']);Carbon::setTestNow();}
 private function pending(string $serial='P-37'):array{$o=Organization::create(['name'=>'Plant','slug'=>strtolower($serial)]);$a=$this->user($o,"a-$serial@test");$v=$this->user($o,"v-$serial@test");$id=$this->actingAs($a)->postJson('/api/devices',['name'=>'Pump','type'=>'sensor','serialNumber'=>$serial,'protocol'=>'mqtt'])->assertCreated()->json('id');$d=Device::findOrFail($id);DeviceAccessAssignment::create(['device_id'=>$id,'user_id'=>$v->id,'access_level'=>'viewer']);app(ResourceRevisionStateService::class)->initializeGrant($v,$d);$this->save($a,$d,'Changed')->assertOk();return[$d,$a,$v];}
 private function save(User $u,Device $d,string $name,int $version=1){return $this->actingAs($u)->patchJson("/api/devices/$d->id/dashboard",['name'=>$name,'layoutVersion'=>$version,'widgets'=>[['id'=>(string)Str::uuid(),'type'=>'status','settings'=>['title'=>'Status','datasource'=>['deviceId'=>(string)$d->id,'telemetryKey'=>'']],'layout'=>['x'=>0,'y'=>0,'w'=>3,'h'=>3]]]]);}private function url(Device $d):string{return "/api/collaboration/resources/device/$d->id/reminder";}private function user(Organization $o,string $e):User{return User::factory()->create(['organization_id'=>$o->id,'email'=>$e,'role'=>'staff','status'=>'active']);} public function test_tomorrow_uses_valid_organization_timezone_and_returns_effective_zone():void{Carbon::setTestNow('2026-08-26 10:00:00 UTC');[$d,,$viewer]=$this->pending('P-72-TZ');$viewer->organization->update(['settings'=>['timezone'=>'Asia/Manila']]);$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'tomorrow'])->assertOk()->assertJsonPath('remindAt','2026-08-27T01:00:00.000000Z')->assertJsonPath('effectiveTimezone','Asia/Manila');Carbon::setTestNow();}
 public function test_cancel_is_user_scoped_increments_generation_and_does_not_change_notification_state():void{[$d,,$viewer]=$this->pending('P-72-CANCEL');$notification=Notification::where(['user_id'=>$viewer->id,'type'=>'revision.available'])->firstOrFail();$beforeRead=$notification->read_at;$beforeDismiss=$notification->dismissed_at;$scheduled=$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'one_hour'])->assertOk()->json();$this->actingAs($viewer)->deleteJson($this->url($d),['user_id'=>$viewer->id])->assertOk()->assertJsonPath('status','cancelled')->assertJsonPath('generation',$scheduled['generation']+1);$notification->refresh();$this->assertEquals($beforeRead,$notification->read_at);$this->assertEquals($beforeDismiss,$notification->dismissed_at);$this->assertDatabaseCount('resource_revision_reminders',1);}
 public function test_unsupported_resource_reminder_and_client_authority_fields_are_rejected():void{[$d,,$viewer]=$this->pending('P-72-VALIDATE');$this->actingAs($viewer)->postJson($this->url($d),['preset'=>'one_hour','generation'=>99])->assertUnprocessable();$this->actingAs($viewer)->postJson("/api/collaboration/resources/dashboard/$d->id/reminder",['preset'=>'one_hour'])->assertUnprocessable();}}
